//! The `bindings/<crate>.agent.md` file: rendering (SPEC 15.4) and staleness (SPEC 15.3).

use super::effects::ProposedEffect;
use super::pipeline::BoundCrate;
use std::path::Path;

const GENERATED_PREFIX: &str = "> generated by agentmark bind \u{2014} ";

/// The two header lines, parsed back. Only the first is machine-read.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Header {
    pub crate_name: String,
    pub version: String,
    pub date: String,
}

/// `> generated by agentmark bind — printpdf 0.7.0 — 2026-10-13`
pub fn parse_header(text: &str) -> Option<Header> {
    let first = text.lines().find(|l| !l.trim().is_empty())?;
    let rest = first.strip_prefix(GENERATED_PREFIX)?;
    let mut parts = rest.split(" \u{2014} ");
    let name_version = parts.next()?;
    let date = parts.next()?.trim().to_string();
    let (crate_name, version) = name_version.rsplit_once(' ')?;
    Some(Header {
        crate_name: crate_name.trim().to_string(),
        version: version.trim().to_string(),
        date,
    })
}

/// State of a binding file relative to the crate version we want.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Freshness {
    Missing,
    /// Header version equals the wanted version.
    Fresh,
    /// Generated for another version: the API may have changed.
    Stale { bound_version: String },
    /// Exists but has no generated header (hand-written, or header deleted): not ours to touch
    /// without `force`.
    Unmanaged,
}

pub fn freshness(path: &Path, want_version: &str) -> std::io::Result<Freshness> {
    let text = match std::fs::read_to_string(path) {
        Ok(t) => t,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Freshness::Missing),
        Err(e) => return Err(e),
    };
    Ok(match parse_header(&text) {
        None => Freshness::Unmanaged,
        Some(h) if h.version == want_version => Freshness::Fresh,
        Some(h) => Freshness::Stale {
            bound_version: h.version,
        },
    })
}

/// The value of the top-level `- effect:` line, if there is one.
pub fn read_effect(text: &str) -> Option<String> {
    text.lines()
        .take_while(|l| !l.starts_with("##"))
        .find_map(|l| l.strip_prefix("- effect:"))
        .map(|v| v.trim().to_string())
}

/// One doc line: a single `>` line, no newlines.
fn doc_line(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Render the whole file. Every bound item gets a `>` line (its summary, or a plain fallback);
/// the effect is always `unverified`.
pub fn render_binding(
    b: &BoundCrate,
    code_lang: &str,
    proposed: ProposedEffect,
    date: &str,
) -> String {
    let mut o = String::new();
    o.push_str(&format!(
        "{GENERATED_PREFIX}{} {} \u{2014} {date}\n",
        b.crate_name, b.version
    ));
    o.push_str(&format!(
        "> edit freely; re-run `agentmark bind {} --force` to regenerate\n",
        b.crate_name
    ));
    o.push_str(&format!("# Binding: {}\n", b.crate_name));
    o.push_str(&format!("- crate: {}\n", b.crate_name));
    o.push_str("- effect: unverified\n");
    o.push_str(&format!("- proposed-effect: {proposed}\n"));
    for it in &b.items {
        o.push('\n');
        let doc = if it.summary.trim().is_empty() {
            format!("Calls `{}`.", it.path)
        } else {
            doc_line(&it.summary)
        };
        o.push_str(&format!("> {doc}\n"));
        o.push_str(&format!("## {}\n", it.sig.heading(&it.name)));
        o.push_str(&format!("  ```{code_lang}\n"));
        for l in it.body.lines() {
            if l.is_empty() {
                o.push('\n');
            } else {
                o.push_str(&format!("  {l}\n"));
            }
        }
        o.push_str("  ```\n");
    }
    if !b.not_bound.is_empty() {
        o.push_str("\n## Not bound\n");
        for (name, reason) in &b.not_bound {
            let r = doc_line(reason);
            if r.is_empty() {
                o.push_str(&format!("- {name}\n"));
            } else {
                o.push_str(&format!("- {name}: {r}\n"));
            }
        }
    }
    o
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn header_round_trip() {
        let h = parse_header(
            "> generated by agentmark bind \u{2014} printpdf 0.7.0 \u{2014} 2026-10-13\n> edit freely\n# Binding: pdf\n",
        )
        .unwrap();
        assert_eq!(h.crate_name, "printpdf");
        assert_eq!(h.version, "0.7.0");
        assert_eq!(h.date, "2026-10-13");
        assert!(parse_header("# Binding: pdf\n").is_none());
    }

    #[test]
    fn effect_line_is_read_from_the_top_only() {
        let t = "# Binding: x\n- crate: x\n- effect: pure\n\n## f()\n- effect: local\n";
        assert_eq!(read_effect(t).as_deref(), Some("pure"));
    }
}
